export const CITY_SEO_TEXTS: Record<string, string> = {
  // ===== ЦФО =====
  moskva: `Москва — крупнейший транспортный узел страны. От МКАД расходятся 12 федеральных трасс: М-1 «Беларусь» на Смоленск и Минск, М-2 «Крым» на Тулу и Белгород, М-3 «Украина» на Калугу и Брянск, М-4 «Дон» на Воронеж и Ростов с продолжением до Краснодара и Сочи, М-5 «Урал» на Рязань и Самару, М-7 «Волга» на Владимир, Нижний Новгород и Казань, М-8 «Холмогоры» на Ярославль и Архангельск, М-9 «Балтия» на Ригу, М-10 «Россия» и платная М-11 «Нева» на Тверь и Петербург. Три аэропорта (Шереметьево, Домодедово, Внуково) плюс Жуковский — мы возим в любой из них в любое время суток. Основной поток — деловые поездки и трансферы в соседние областные центры (Тула, Калуга, Тверь, Владимир, Рязань — 1.5-3 часа), летом массово на юг (Краснодар, Сочи, Анапа, Крым) на машинах с багажным минивэном. Зимой добавляются горнолыжные направления — Красная Поляна через М-4. Корпоративные клиенты — отдельный пул: безналичный расчёт с НДС, выделенный менеджер, ежемесячный счёт.`,

  // (Воронеж/Калуга/Тверь/Ярославль/Владимир/Орёл/Курск/Белгород — ниже, в блоке пилотов)

  tula: `Тула — 180 км от Москвы по М-2 «Крым» (2 часа). Деловые трансферы в Москву и обратно — основной поток: выезд в 6 утра под 10-часовые встречи, обратный рейс вечером. Аэропорт Клоково не принимает гражданские рейсы, поэтому возим во все три московских аэропорта (Внуково 200 км, Домодедово 220, Шереметьево 250). По Тульской области — Алексин, Новомосковск, Узловая, Щёкино, Ясная Поляна. На юг — Орёл (180 км по Р-92), Курск (370). Сильный туристический поток — Куликово поле, Поленово, Тарханы. По М-4 на восток через Каширу удобно ехать в Рязань (250 км), летом — в Воронеж и дальше к морю.`,

  bryansk: `Брянск стоит на М-3 «Украина», 380 км до Москвы (5-6 часов), 380 до Гомеля, 230 до Орла, 360 до Смоленска. Из-за ограничений на белорусском направлении основной поток сейчас — Москва (Внуково/Домодедово/Шереметьево, 380-430 км), Орёл, Калуга. Аэропорт Брянск принимает ограниченное число рейсов, для большинства международных перелётов выгоднее в Москву. По области возим в Клинцы, Стародуб, Унечу, Карачев, Жуковку. После 2022 года добавились поездки в приграничные районы Брянской области (Климово, Севск, Суземка) — с учётом оперативной обстановки. Лесной край, дороги местами разбитые — летом удобно работать кроссовером или минивэном.`,

  ryazan: `Рязань — 200 км от Москвы по М-5 «Урал» (2.5-3 часа). Сильный поток деловых поездок в столицу: выезд под утренние встречи в 5-6 утра, в Москве к 9. Трансферы в Домодедово (180 км, 2.5 часа) и Внуково (210 км) — каждый день. По Рязанской области — Касимов, Скопин, Михайлов, Рыбное, Сасово. Сильное туристическое направление — Константиново (родина Есенина, 40 км) и Солотча. На юг через М-6 — Тамбов (250 км) и далее Волгоград. На восток по М-5 — Пенза (450 км), Саранск (340). Из Рязани часто едут в Тулу (180 км по региональным трассам) и Владимир (240).`,

  ivanovo: `Иваново — 280 км от Москвы по М-7 «Волга» с поворотом на Р-79, 4-5 часов в пути. Аэропорт Южный обслуживает в основном региональные рейсы — для большинства международных перелётов едем в Шереметьево или Внуково (4 часа). По Ивановской области — Шуя, Кохма, Тейково, Палех (родина лаковой миниатюры), Кинешма. На Волге — Плёс (60 км, 1 час), один из самых популярных туристических маршрутов. Связь с соседями — Ярославль (110 км по Р-79), Кострома (100), Владимир (110), Нижний Новгород (240). Текстильные предприятия и текстильный кластер — поток деловых поездок к фабрикам.`,

  kostroma: `Кострома стоит на М-8 «Холмогоры» с ответвлением Р-243, 340 км до Москвы (4-5 часов). Один из основных городов Золотого кольца, поэтому летом сильный туристический поток: возим группы по маршруту Кострома — Ярославль — Ростов — Переславль — Сергиев Посад с остановками. Аэропорт Сокеркино работает в ограниченном режиме, большинство международных рейсов — через Москву (Шереметьево/Внуково, 340-380 км). По области — Нерехта, Галич, Шарья, Мантурово. Связь с Волгой и круизными теплоходами: подаём машину к Речному вокзалу под прибытие. Часто строим связки Кострома — Иваново — Плёс, Кострома — Ярославль — Углич.`,

  smolensk: `Смоленск — пограничный город на М-1 «Беларусь», 400 км до Москвы (5 часов), 75 до белорусской границы (Красный/Рудня), 240 до Витебска. Аэропорт Смоленск-Северный не принимает гражданские рейсы, поэтому возим в Москву (Внуково/Домодедово/Шереметьево, 380-430 км). По области — Вязьма, Гагарин (родина Юрия Гагарина), Ярцево, Рославль, Сафоново. С учётом ограничений на белорусском направлении деловой поток в Беларусь сократился, но грузовые и частные поездки в Минск и Витебск продолжаются — оформляем документы и работаем по существующему регламенту. Историко-туристический маршрут — Хмелита, Талашкино, Гнёздово.`,

  lipetsk: `Липецк — 480 км от Москвы по Р-119 и М-4. Промышленный центр (НЛМК — Новолипецкий металлургический комбинат), поэтому основной поток — корпоративные трансферы в Москву и Воронеж. Аэропорт Липецк принимает ограниченные рейсы, для большинства направлений едем в Москву (480 км, 6 часов) или Воронеж (130 км, 2 часа). По области — Елец, Грязи, Данков, Усмань, Задонск. На юг по М-4 — Воронеж и далее к морю; на север — Тула (300 км), Москва. Корпоративные договоры с НЛМК и спутниковыми предприятиями: выделенный менеджер, безналичный расчёт с НДС, подача к КПП завода.`,

  tambov: `Тамбов — 470 км от Москвы по Р-22 «Каспий», 6-7 часов. Аэропорт Донское не принимает регулярные пассажирские рейсы, поэтому возим в Москву (Домодедово 470 км) или Воронеж (210 км, 3 часа). По области — Мичуринск, Котовск, Моршанск, Рассказово, Уварово. Сильный поток — деловые поездки в Москву (выезжаем ночью под утренние встречи) и трансферы к московским аэропортам. С Воронежем стабильная связь — едем туда под рейсы и обратно. Туристические направления — усадьба Асеевых, музей-усадьба Рахманинова в Ивановке. Часто работаем с агропромышленными предприятиями Тамбовской области по корпоративным договорам.`,

  // ===== СЗФО =====
  'sankt-peterburg': `Санкт-Петербург — северная столица и второй по объёму транспортный узел страны. От города идут М-10 «Россия» и платная М-11 «Нева» на Москву, А-180 «Нарва» на Эстонию, А-181 «Скандинавия» на Финляндию, Р-21 «Кола» на Мурманск, Р-23 на Псков, А-114 на Вологду. Аэропорт Пулково — единственный международный на северо-западе, поэтому подача от/до Пулково — самый частый запрос. Маршрут СПб — Москва по М-11 занимает 6-7 часов против 8-10 по М-10: платный участок включаем в финальную цену поездки. Сильное петрозаводское и карельское направление — Рускеала, Сортавала, Кижи (через Петрозаводск). Летом возим в Эстонию через Нарву (граница работает), в Финляндию направления заморожены. Деловые поездки в Великий Новгород (190 км, 2.5 часа), Псков (280 км), Выборг (130) и пригороды — Гатчина, Петергоф, Пушкин. Крупный поток — трансферы из круизных терминалов и Морского вокзала.`,

  pskov: `Псков — пограничный город на М-20, 280 км до Петербурга (4 часа), 730 до Москвы, 30 до эстонской границы (Куничина Гора). Аэропорт Псков обслуживает ограниченное число рейсов, поэтому основной поток — Петербург (трансферы в Пулково, деловые поездки) и Москва (Шереметьево/Внуково/Домодедово, 7-9 часов, выезд ночью). По области — Великие Луки (320 км), Остров, Печоры (54 км, Псково-Печерский монастырь), Пушкинские Горы (110 км). Сильное паломническое направление — монастыри Псковщины. С эстонской границы — групповые поездки в Тарту и Таллин (работают пограничные пункты Куничина Гора и Шумилкино). Историко-туристический поток летом — Изборск, Печоры, Михайловское.`,

  vologda: `Вологда — узел северного транспортного коридора. Отсюда едем в Архангельск, Петрозаводск, Великий Устюг, Кириллов и Белозерск по М-8 «Холмогоры» и северным региональным трассам. Вологодский аэропорт обслуживает только внутрироссийские региональные рейсы, поэтому трансферы до Шереметьево и Пулково — одно из основных направлений: 7-8 часов до Москвы, 8-9 до Петербурга, выезжаем накануне вечером или ночью, чтобы успеть к утренним вылетам. Зимой добавляются сезонные поездки на Север (Соловки через Рабочеостровск, Каргополь, Вологодская губа), летом — туристические маршруты по Русскому Северу. Вологодские зимы жёсткие: работаем на машинах с подогревом, шипованой резиной и запасом тёплой воды — дорога до Великого Устюга в феврале это не прогулка.`,

  cherepovec: `Череповец — промышленный центр Северо-Запада, 130 км от Вологды, 600 км от Москвы. Главный работодатель — «Северсталь», поэтому основной поток поездок корпоративный: трансферы в Шереметьево (590 км по М-8) и Пулково (550 км по А-114), командировки в Москву и Петербург, регулярные рейсы между Череповцом и Вологдой. Аэропорт Череповец обслуживает ограниченное число внутрироссийских направлений. Дальше по А-114 на запад — Тихвин и Петербург; по М-8 на юг — Ярославль (260 км), на север — Вологда и Архангельск (700 км). По области — Кадуй, Шексна, Белозерск (туризм), Кириллов (Кирилло-Белозерский монастырь). Зимой работаем с прогревом — северные дороги требуют запаса.`,

  petrozavodsk: `Петрозаводск — столица Карелии, 430 км от Петербурга по Р-21 «Кола» (6 часов), 1000 км от Москвы. Аэропорт Бесовец принимает ограниченное число внутрироссийских рейсов, поэтому большинство трансферов — в Пулково. Сильнейшее туристическое направление — Карелия: Кижи (через Петрозаводский залив или круиз), Валаам, Рускеала (мраморный карьер, 270 км), Сортавала (250 км, недавно реконструирована трасса), горный парк Рускеала, водопады Кивач. Финская граница (МАПП Вяртсиля, Люття) закрыта для туристического движения с 2024 года; маршруты на Финляндию приостановлены. По Карелии возим в Кондопогу, Медвежьегорск, Беломорск, Сегежу.`,

  arhangelsk: `Архангельск стоит на М-8 «Холмогоры», 1200 км от Москвы (15-17 часов), 800 от Петербурга. Аэропорт Талаги принимает рейсы из Москвы, Петербурга, Мурманска и ряда других городов — но трансферы к нему регулярные. Сильное направление — Северодвинск (50 км, оборонное судостроение), Новодвинск, Котлас (600 км). Основной туристический поток — Соловецкие острова: возим до Рабочеостровска (Карелия, 700 км) или Беломорска под катер на Соловки; зимой — через Архангельск на самолёте до Соловков. Поездки в Холмогоры (родина Ломоносова), Малые Корелы. Зимой работаем только на машинах с подогревом и зимней резиной — северные трассы зимой требуют запаса в багажнике.`,

  murmansk: `Мурманск — самый северный областной центр России, 1500 км от Петербурга по Р-21 «Кола» (18-20 часов), 2000 от Москвы. Аэропорт Мурманск — основной транспортный узел Заполярья, к нему возим из соседних городов области. Главные туристические потоки — северное сияние (зимой), Териберка (130 км, прославилась после фильма «Левиафан»), Хибины и Кировск (220 км), Полярный, Североморск. Финская граница (Лотта) закрыта с 2022 года. Норвежская граница (Борисоглебск-Стурскуг) работает, но с ограничениями — туристические поездки приостановлены, рабочие визиты по разрешению. По области — Мончегорск, Апатиты (220 км), Кандалакша (240), Никель. Зимой работаем только на полноприводных машинах с шипами — другого варианта нет.`,

  'velikiy-novgorod': `Великий Новгород — древнерусская столица, 190 км от Петербурга по М-10 (2.5 часа), 530 от Москвы. Аэропорт Кречевицы не принимает гражданские рейсы — все трансферы через Пулково или московские аэропорты. Сильное туристическое направление: Софийский собор, Юрьев монастырь, Витославлицы, Старая Русса (90 км, 1 час). По области возим в Боровичи, Валдай (140 км, национальный парк), Демянск, Холм. Связь с соседями — Псков (210 км, 3 часа), Тверь (340 км). Деловой поток с Петербургом стабильный: Великий Новгород входит в петербургскую агломерацию по транспортной логике, многие работают/учатся в обеих столицах.`,

  syktyvkar: `Сыктывкар — столица Республики Коми, 1300 км от Москвы (16-18 часов), 1100 от Петербурга. Аэропорт Сыктывкар — основной транспортный узел Коми, к нему возим из городов республики. По Коми — Ухта (380 км), Воркута (1100 км по железной дороге; автомобильное сообщение только до Усинска), Сосногорск, Печора, Усинск. Сильное промышленное направление — нефтегаз (Лукойл-Коми, Усинск). Туристический поток — Парма, Финно-Угорский этнопарк. Зимой работаем только на машинах с подогревом и шипованой резиной; летом — на части северных направлений дороги грунтовые, нужен внедорожник или подготовленный кроссовер.`,

  // ===== ЮФО =====
  krasnodar: `Краснодар — главный южный узел: М-4 «Дон» на Москву (1380 км, 16-18 часов), А-289 на Темрюк и Крымский мост, М-25 на Новороссийск и далее курорты Чёрного моря. Международный аэропорт Пашковский — один из крупнейших на юге, принимает рейсы из Москвы, Петербурга, регионов и часть зарубежных. Самый сильный поток — курортный: летом сотни поездок в Анапу (160 км, 2.5 часа), Геленджик (170, 2.5), Новороссийск (140, 2), Сочи (270, 4), Адлер (290), Красную Поляну (310). Зимой — горнолыжные курорты Красной Поляны. По Краснодарскому краю — Армавир (200 км), Сочи, Туапсе, Лазаревское, Адлер. На восток — Ставрополь (320), КМВ (550). На запад — Темрюк и Крымский мост на Симферополь и Севастополь. Деловой поток — корпоративные клиенты в АПК и логистике юга России.`,

  'rostov-na-donu': `Ростов-на-Дону стоит на М-4 «Дон», 1100 км от Москвы (12-14 часов), 270 от Краснодара (3 часа). Международный аэропорт Платов — современный, принимает рейсы из Москвы, Петербурга, регионов. Возим к/от Платова постоянно. По области и соседям: Таганрог (70 км, 1 час), Новочеркасск (40), Шахты (75), Сальск (190), Волгодонск (240). На юг — Краснодар (270 км), Ставрополь (430), КМВ (560). На север — Воронеж (550 км, 6-7 часов), Москва (1100). Сильное направление — Крым через Краснодар и Крымский мост (700 км до Симферополя). С 2022 года добавились маршруты по ЛНР и ДНР: Луганск (130 км), Донецк (190), Мариуполь (190), Бердянск (310) — водители знают актуальную обстановку, документы оформлены. Часто работаем с корпоративными клиентами Ростсельмаша, портовой логистики, АПК Ростовской области.`,

  volgograd: `Волгоград стоит на Р-22 «Каспий» и А-260 «Каспий», 1000 км от Москвы (12-14 часов), 480 до Ростова, 580 до Астрахани, 380 до Саратова. Международный аэропорт Гумрак принимает рейсы из Москвы, Петербурга, Сочи, регионов. Сильное туристическое направление — Мамаев Курган и музей-панорама Сталинградской битвы (привозим экскурсионные группы), Волго-Донской канал, Городище. По области — Волжский (20 км), Камышин (190), Михайловка (200), Урюпинск (340). На юг — Элиста (300 км, 4 часа), Астрахань (580). На север — Саратов (380), Воронеж (570), Москва (1000). Корпоративные клиенты — Волгоградский алюминиевый завод, нефтехимия, металлургия. Летом много южных трансферов через Волгоград в сторону КМВ и Каспийского моря.`,

  astrahan: `Астрахань — южная точка Поволжья на Р-22 «Каспий», 1400 км от Москвы (18-20 часов), 580 от Волгограда (7-8). Международный аэропорт Нариманово принимает рейсы из Москвы, Петербурга, регионов. Сильнейшая специфика — Каспийское море и дельта Волги: рыболовные базы Камызякского, Икрянинского, Володарского районов, лотосовые поля (август). Туристический поток — Кремль, Знаменская улица, Соляное озеро Баскунчак (300 км). Деловые поездки — нефтегаз (Лукойл-Нижневолжскнефть, Каспийская нефтегазовая провинция), судостроение (ОСК), порт. По области — Ахтубинск, Знаменск, Володарский. На границу с Казахстаном (Караозек, Малый Арал) — рабочие и туристические рейсы. Летом жара 40+, работаем на машинах с кондиционером и запасом питьевой воды.`,

  krym: `Крым — спецрегион через Крымский мост (А-290, со стороны Краснодара). Из Москвы — 1700 км до Симферополя по М-4 и А-289 (20-22 часа), с одной обязательной остановкой на отдых водителя. Главные направления — Симферополь (аэропорт, центр), Севастополь (80 км от Симферополя), Ялта (90), Алушта (50), Евпатория (75), Феодосия (110), Керчь (210). Аэропорт Симферополь работал до 2022 года, сейчас закрыт — большинство добирается на машине или по железной дороге. Летом массовый курортный поток с материка — семьи с багажом выбирают минивэн (до 6 пассажиров). По Крыму возим между курортами, на Ай-Петри, в Бахчисарай, на Тарханкут. Учитываем оперативную обстановку на трассах — диспетчер уточняет ситуацию перед выездом.`,

  elista: `Элиста — столица Калмыкии, 300 км от Волгограда (4 часа), 290 от Ставрополя (4), 360 от Астрахани, 1400 от Москвы. Аэропорт Элиста принимает ограниченные рейсы из Москвы. Уникальная буддистская культура — Золотая обитель Будды Шакьямуни, Сити-Чесс, степи Калмыкии (национальный парк «Чёрные земли»). По республике — Лагань, Городовиковск, Яшалта, Цаган-Аман. На юг — Ставрополь и КМВ; на восток — Астрахань; на север — Волгоград. Степные дороги летом сухие и быстрые, зимой могут заметать — работаем с прогнозом погоды. Часто работаем с делегациями буддистских паломников из Бурятии, Тувы и Монголии.`,

  // ===== СКФО =====
  stavropol: `Ставрополь стоит на М-29 «Кавказ», 320 км от Краснодара (4 часа), 280 от КМВ (Минеральные Воды), 1450 от Москвы. Аэропорт Шпаковское принимает ограниченные рейсы — большинство международных через Минводы (220 км). Самый сильный поток из Ставрополя — Кавказские Минеральные Воды: Пятигорск (170 км), Кисловодск (220), Ессентуки (190), Железноводск (200), Минеральные Воды (220, аэропорт). По Ставропольскому краю — Невинномысск (60 км), Михайловск, Будённовск (220), Светлоград, Изобильный. Часто возим экскурсионные группы по Северному Кавказу: Архыз (270 км), Домбай (300), Эльбрус (320), Чегет, Терскол. На юг — Нальчик (240 км), Владикавказ (380), Грозный (370). По КМВ — лечебные туры на 14-21 день, везём с багажом и обратно.`,

  // ===== ПФО =====
  ufa: `Уфа — столица Башкортостана, узел М-5 «Урал» (1500 км до Москвы, 17-19 часов) и Р-240 на Оренбург. Международный аэропорт Уфа принимает рейсы из Москвы, Петербурга, регионов и часть стран СНГ. Возим к/от аэропорта постоянно. По Башкирии — Стерлитамак (130 км), Салават (170), Нефтекамск (210), Октябрьский (180), Сибай (450). Сильный поток — нефтегазовый сектор (Башнефть, Лукойл-Уралнефтепродукт, Газпром нефтехим Салават), туры в Шульган-Таш (Каповая пещера, 350 км), Иремель, Янган-Тау. На запад — Казань (530 км, 7 часов), на восток — Челябинск (470, 6), на юг — Оренбург (380), на север — Пермь (490). Башкирия — горно-лесная республика, зимой дороги к удалённым точкам требуют полноприводных машин.`,

  kazan: `Казань — столица Татарстана и крупный поволжский узел: М-7 «Волга» (820 км до Москвы, 10-12 часов), Р-239 на Оренбург, Р-241 на Йошкар-Олу. Международный аэропорт Казань принимает рейсы из Москвы, Петербурга, регионов и стран СНГ. Сильнейший туристический поток — Казанский кремль, Кул-Шариф, остров Свияжск (60 км, 1 час), Болгар (200 км). По Татарстану — Набережные Челны (240 км, КамАЗ), Нижнекамск (240), Альметьевск (270, Татнефть), Бугульма (350), Зеленодольск (40). Сильное промышленное направление — КамАЗ (поставщики, командировки в Набережные Челны), Татнефть (Альметьевск, Лениногорск), нефтехимия Нижнекамска. Связь с Нижним Новгородом (400 км, 5 часов), Чебоксарами (140, 2), Ульяновском (220), Самарой (380), Йошкар-Олой (140). Корпоративные договоры с татарстанскими ИТ-компаниями и Иннополисом.`,

  samara: `Самара — крупный поволжский центр на М-5 «Урал», 1000 км от Москвы (12-14 часов). Международный аэропорт Курумоч принимает рейсы из Москвы, Петербурга, регионов и часть стран СНГ. По области — Тольятти (80 км, АВТОВАЗ — крупный поток корпоративных трансферов), Сызрань (130), Новокуйбышевск (20), Чапаевск (40), Жигулёвск (90, Жигулёвские горы). Сильнейшая специфика — АВТОВАЗ в Тольятти: поставщики, командировки, сменные смены — возим прямо к корпусам ВАЗа и Renault Russia. На запад — Пенза (430 км), Саратов (440), Москва. На восток — Уфа (470 км, 6 часов), Оренбург (440). На север — Ульяновск (220 км, 3 часа), Казань (380). Туристический поток летом — Жигулёвские горы, Самарская Лука, Рачейка.`,

  orenburg: `Оренбург — пограничный город на казахстанской границе, 1450 км от Москвы (18-20 часов), 380 от Уфы (5), 440 от Самары. Международный аэропорт Оренбург (Центральный) принимает рейсы из Москвы, Петербурга, регионов. Сильное направление — пограничные пункты с Казахстаном: Илек, Сагарчин, Орск (через границу до Актобе 100 км). По области — Орск (300 км, металлургия Уральская сталь), Новотроицк (290), Бузулук (250, нефть), Соль-Илецк (70, солёное озеро — массовый летний поток). Туристический пик — июль-август в Соль-Илецке, везём с пляжными принадлежностями. На север — Уфа и Челябинск (730 км), Магнитогорск (390). На запад — Самара (440), на юг — граница с Казахстаном.`,

  izhevsk: `Ижевск — столица Удмуртии, 1100 км от Москвы (14-16 часов), 380 от Казани (5), 280 от Перми. Аэропорт Ижевск принимает рейсы из Москвы, Петербурга, Сочи. Самая известная специфика — Концерн «Калашников» (оборонка) и оружейное производство. Деловые трансферы — командировки на «Ижсталь», «Ижмаш», автозавод. По Удмуртии — Воткинск (60 км, родина Чайковского), Сарапул (60), Глазов (170), Можга (90). Связь с соседями — Пермь (280 км, 4 часа), Казань (380, 5), Йошкар-Ола (340), Киров (300), Уфа (430). Зимой дороги Удмуртии могут быть в снежной каше — работаем на шипованой резине.`,

  'nizhniy-novgorod': `Нижний Новгород стоит на М-7 «Волга», 420 км от Москвы (5-6 часов), 380 от Казани (5). Международный аэропорт Стригино принимает рейсы из Москвы, Петербурга, регионов, СНГ. По области — Дзержинск (35 км, химия), Бор (15), Кстово (30), Арзамас (110), Городец, Семёнов (туризм, хохлома). Сильное направление — авиапром (Сокол), судостроение, ГАЗ — корпоративные клиенты возят сотрудников. Туристический поток — Большое Болдино (220 км, Пушкинские места), Дивеево (180, монастырь Серафима Саровского), Городец. Связь с соседями — Владимир (230 км, 3 часа), Иваново (240), Чебоксары (250), Йошкар-Ола (270), Киров (480). Летом круизные теплоходы с Волги — подаём машину к Речному вокзалу.`,

  saratov: `Саратов — поволжский центр на Р-22 «Каспий», 850 км от Москвы (10-12 часов), 440 от Самары, 380 от Волгограда. Международный аэропорт Гагарин (открыт в 2019, заменил старый Центральный) принимает рейсы из Москвы, Петербурга, регионов. По области — Энгельс (10 км, через Волгу), Балашов (220), Балаково (160), Пугачёв (240). Сильное направление — авиапром (Саратовский авиазавод, Гагаринский), нефтегаз. Туристический поток — Парк Победы на Соколовой горе, Хвалынск (220 км, горнолыжный комплекс зимой), Утёс Степана Разина. Связь с соседями — Самара (440 км, 5-6 часов), Пенза (240), Тамбов (380), Волгоград (380). Летом — поездки к Волге, на пляжи Энгельса.`,

  ulyanovsk: `Ульяновск стоит на Р-228 «Поволжье», 870 км от Москвы (11-12 часов), 220 от Самары, 220 от Казани. Аэропорт Восточный (Ульяновск-Восточный) принимает рейсы из Москвы, Петербурга. Аэропорт Ульяновск-Баратаевка обслуживает в основном внутрироссийские маршруты. По области — Димитровград (90 км, ГНЦ НИИАР), Инза, Барыш, Сенгилей. Сильное направление — автопром (УАЗ), авиапром (Авиастар-СП — Ил-76, Ил-78), Авиационный завод. Туристический поток — родина Ленина (музеи, ул. Гончарова), музей-усадьба «Языково». Связь с соседями — Самара (220 км, 3 часа), Казань (220, 3), Пенза (240), Саратов (340), Чебоксары (220). На юг по М-5 — Сызрань (130 км).`,

  kirov: `Киров — северо-восточный поволжский город на Р-243 «Кострома — Пермь», 950 км от Москвы (12-14 часов), 300 от Ижевска, 480 от Нижнего Новгорода, 490 от Перми. Аэропорт Победилово принимает рейсы из Москвы, Петербурга, регионов. По области — Кирово-Чепецк (40 км, химия, удобрения), Слободской, Котельнич, Вятские Поляны. Сильное направление — деревянное ремесленное производство (хохлома, дымковская игрушка), туризм (Великорецкий крестный ход). Связь с соседями — Пермь (490 км, 7 часов), Ижевск (300), Йошкар-Ола (220), Кострома (640), Нижний Новгород (480). Зимой дороги Кировской области могут быть тяжёлыми — север с дождями переходящими в снег с октября.`,

  cheboksary: `Чебоксары — столица Чувашии, узел М-7 «Волга», 650 км от Москвы (8-10 часов), 140 от Казани (2), 250 от Нижнего Новгорода. Аэропорт Чебоксары принимает рейсы из Москвы, Петербурга, регионов. По Чувашии — Новочебоксарск (15 км), Канаш (80), Алатырь (180), Ядрин. Сильное направление — Чебоксарский тракторный завод (ЧТЗ, бывший «Промтрактор»), химия, текстиль. Туристический поток — Чувашский национальный музей, Музей пива. Связь с соседями — Казань (140 км, 2 часа), Йошкар-Ола (90, 1.5), Нижний Новгород (250, 3), Ульяновск (220), Саранск (220). Часто заказывают трансферы Чебоксары — Казань (Универсиада, ИТ-кластер) и Чебоксары — Нижний Новгород по М-7.`,

  'yoshkar-ola': `Йошкар-Ола — столица Республики Марий Эл, ответвление от М-7 «Волга», 730 км от Москвы (9-11 часов), 140 от Казани, 90 от Чебоксар, 270 от Нижнего Новгорода. Аэропорт Йошкар-Ола обслуживает ограниченные внутрироссийские рейсы — большинство международных через Казань. По республике — Волжск (90 км), Звенигово, Козьмодемьянск, Семёновка. Сильное направление — машиностроение, лесопромышленный комплекс. Туристический поток — Венецианский комплекс набережной Брюгге, Кокшайск (на Волге). Связь с соседями — Казань (140 км, 2 часа), Чебоксары (90, 1.5), Киров (340), Нижний Новгород (270). Лес и грунтовые дороги по республике летом — иногда нужен кроссовер.`,

  saransk: `Саранск — столица Мордовии, 640 км от Москвы (8-9 часов), 340 от Рязани, 220 от Чебоксар, 220 от Пензы. Аэропорт Саранск принимает рейсы из Москвы. По Мордовии — Рузаевка (25 км), Краснослободск, Ковылкино, Темников. Сильное направление — электротехника, оптика, светотехника (Саранскэлектросвет). Туристический поток — Темников и Санаксарский монастырь, Дивеево через Темников. Связь с соседями — Пенза (220 км, 3 часа), Рязань (340), Ульяновск (240), Чебоксары (220), Нижний Новгород (290). На запад — Рязань и Москва; на восток — Ульяновск и Самара. Сильное направление с 2018 года — туризм после ЧМ (Саранск принимал матчи).`,

  penza: `Пенза стоит на М-5 «Урал», 630 км от Москвы (8-10 часов), 430 от Самары, 240 от Саратова, 220 от Саранска. Аэропорт Пенза принимает рейсы из Москвы, Петербурга, Сочи. По области — Заречный (10 км, закрытый город, требуется пропуск), Сердобск (90), Кузнецк (130), Никольск. Сильное направление — приборостроение, машиностроение, ВПК. Туристический поток — родина Лермонтова (Тарханы, 100 км), Наровчат (150). Связь с соседями — Саратов (240 км, 3 часа), Тамбов (260), Рязань (450), Ульяновск (240), Саранск (220), Самара (430). На запад — Москва по М-5; на восток — Самара. Корпоративные клиенты в Заречном — отдельный сегмент с пропускной системой.`,

  perm: `Пермь — крупный уральский центр на Р-242, 1400 км от Москвы (17-20 часов), 280 от Ижевска, 360 от Екатеринбурга, 490 от Уфы. Международный аэропорт Большое Савино принимает рейсы из Москвы, Петербурга, регионов, СНГ. По Пермскому краю — Березники (170 км, химия, калий), Соликамск (200), Краснокамск (35), Кунгур (90, Кунгурская ледяная пещера — туризм). Сильное направление — нефтегаз (Лукойл-Пермь), химия (Уралкалий), металлургия. Туристический поток — Кунгурская пещера, Хохловка (этнопарк), Белогорский монастырь. Связь с соседями — Екатеринбург (360 км, 5 часов), Ижевск (280), Уфа (490), Киров (490), Нижний Тагил (510). Зимы суровые, шипы и подогрев — обязательное оснащение.`,

  // ===== УФО =====
  ekaterinburg: `Екатеринбург — столица Урала, узел М-5 «Урал», 1800 км от Москвы (22-24 часа), 200 от Челябинска (3), 360 от Перми. Международный аэропорт Кольцово принимает рейсы из Москвы, Петербурга, регионов, СНГ и часть международных. Сильнейший корпоративный поток — Уральский регион промышленный (УГМК, ТМК, Уралмаш, Уралвагонзавод в Нижнем Тагиле). По Свердловской области — Нижний Тагил (140 км), Каменск-Уральский (100), Первоуральск (50), Серов (350), Краснотурьинск (440). Туристический поток — Ганина Яма (40 км), Висим (бажовские места), Невьянск (90 км, Невьянская башня), горнолыжный парк Уктус. Связь с соседями — Челябинск (200 км, 3 часа), Тюмень (320, 4-5), Пермь (360), Уфа (470), Курган (370). Зимой работаем только на машинах с шипами и подогревом.`,

  chelyabinsk: `Челябинск — крупный уральский центр на М-5 «Урал», 1750 км от Москвы (22-24 часа), 200 от Екатеринбурга (3), 470 от Уфы, 370 от Кургана. Международный аэропорт Баландино принимает рейсы из Москвы, Петербурга, регионов. По Челябинской области — Магнитогорск (310 км, ММК — Магнитогорский металлургический комбинат), Златоуст (150), Миасс (95), Озёрск (110, закрытый), Касли. Сильное направление — металлургия (ЧТПЗ, ЧМК, ММК), машиностроение (ЧТЗ — Челябинский тракторный), оружие (Озёрск). Туристический поток — Таганай (160 км, нац. парк), Тургояк (120 км, чистейшее озеро), Зюраткуль. Связь с соседями — Екатеринбург (200 км, 3 часа), Уфа (470), Курган (370), Магнитогорск (310). Зимой работаем шипованой резиной обязательно.`,

  kurgan: `Курган стоит на Р-254 «Иртыш», 1900 км от Москвы (23-25 часов), 370 от Челябинска, 370 от Екатеринбурга, 400 от Тюмени. Аэропорт Курган принимает ограниченные рейсы — большинство международных через Челябинск или Тюмень. По области — Шадринск (150 км), Куртамыш, Шумиха, Далматово. Сильное направление — машиностроение (Курганмашзавод, Курганский автобусный), сельское хозяйство. Связь с соседями — Челябинск (370 км, 5 часов), Екатеринбург (370), Тюмень (400, 5), Омск (650 км, 8). Курганская область — преимущественно равнинная, дороги хорошие летом, зимой могут заметать степи.`,

  tyumen: `Тюмень — нефтегазовый центр на Р-254 «Иртыш», 2100 км от Москвы (24-26 часов), 320 от Екатеринбурга (4-5), 400 от Кургана. Международный аэропорт Рощино принимает рейсы из Москвы, Петербурга, регионов, СНГ. Сильнейшее направление — командировки в нефтегазовые регионы: ХМАО (Сургут 700 км, Нижневартовск 800), ЯНАО (Новый Уренгой 1300, Ноябрьск 950, Салехард 1700), Тобольск (250 км, нефтехимия СИБУРа). По области — Ишим (320), Ялуторовск, Заводоуковск. Корпоративные клиенты — Газпром, Лукойл-Западная Сибирь, Сургутнефтегаз — командировки и трансферы со сменным графиком. Связь с соседями — Екатеринбург (320 км, 4-5 часов), Курган (400), Омск (610), Челябинск (520). Зимой дороги до Югры и Ямала могут быть тяжёлыми, нужны опыт и подготовка.`,

  'hanty-mansiysk': `Ханты-Мансийск — столица ХМАО, нефтегазовый регион, 2400 км от Москвы (с двумя пересадками или 28-30 часов на машине). Аэропорт Ханты-Мансийск — основной транспортный узел Югры, к нему возим из соседних городов. По ХМАО — Сургут (300 км, 4 часа), Нефтеюганск (270), Нижневартовск (470), Нягань (390), Когалым (370). Сильнейшее направление — нефтегаз: Лукойл (Когалым), Сургутнефтегаз (Сургут), Газпром нефть. Корпоративные клиенты — командировки на месторождения, трансферы со сменным графиком (28/28 дней). По соседям — Тюмень (700 км, 9-10 часов), Тобольск (470). Туризм — резко сезонный (рыбалка летом, охота). Зимой работаем только на полноприводных машинах с подогревом, летом часть дорог к удалённым месторождениям — техногрунтовка, нужен подходящий транспорт.`,

  surgut: `Сургут — крупнейший город Югры, центр нефтегазового кластера, 2700 км от Москвы, 300 от Ханты-Мансийска (4 часа), 700 от Тюмени (9-10). Аэропорт Сургут принимает рейсы из Москвы, Петербурга, регионов, СНГ. По окрестностям — Нефтеюганск (60 км), Лянтор (70), Когалым (180), Нижневартовск (220). Сильнейшее направление — Сургутнефтегаз, Газпром, нефтесервис, командировки на месторождения. Сменный график 28/28 или 14/14 — массовые корпоративные трансферы со сменами. На юг — Тюмень (700 км), Екатеринбург (1000). Часто работаем с вахтовыми рабочими — посадка от подъезда, выезд накануне вечером под утренние вылеты. Зимы суровые (до −40°C), работаем только на машинах с автономным подогревом, шипами и зимним пакетом.`,

  // ===== СФО =====
  novosibirsk: `Новосибирск — столица Сибири на Р-254 «Иртыш» и Р-255 «Сибирь», 3400 км от Москвы (40-44 часа), 700 от Омска (9), 380 от Барнаула, 770 от Кемерово. Международный аэропорт Толмачёво — один из крупнейших в стране, принимает рейсы из Москвы, Петербурга, регионов, СНГ и Азии. По области — Бердск (40 км), Искитим (60), Куйбышев, Татарск, Карасук. Сильное направление — Академгородок (наука, ИТ-кластер), машиностроение, авиапром (Чкаловский). Туристический поток — Алтай через Барнаул (380 км до Барнаула + 200 до Горно-Алтайска), Карасукская степь. Связь с соседями — Кемерово (250 км, 3-4 часа), Барнаул (380, 5), Томск (270, 4), Омск (650, 8-9). Часто строим связки Новосибирск — Барнаул — Горно-Алтайск летом для туристических групп.`,

  krasnoyarsk: `Красноярск — крупный сибирский центр на Р-255 «Сибирь», 4100 км от Москвы (на машине почти невозможно), 800 от Новосибирска (10-12 часов), 1100 от Иркутска. Международный аэропорт Емельяново принимает рейсы из Москвы, Петербурга, регионов, СНГ и Азии. По Красноярскому краю — Дивногорск (40 км, ГЭС), Сосновоборск (35), Железногорск (60, закрытый), Канск (240), Ачинск (180, глинозём), Норильск (только авиа). Сильное направление — Норильский никель (вахтовики на Норильск через Емельяново), РУСАЛ, СУЭК. Туристический поток — Столбы (заповедник на окраине), Шушенское, Дивногорск, Енисей. Связь с соседями — Иркутск (1100 км, 14 часов), Кемерово (560, 7), Новосибирск (800, 10), Абакан (440). Зимы суровые, по краю много грунтовок — летом и зимой нужна подготовленная техника.`,

  tomsk: `Томск стоит на Р-255 «Сибирь», 3600 км от Москвы, 270 от Новосибирска (3-4 часа), 600 от Кемерово. Аэропорт Богашёво принимает рейсы из Москвы, Петербурга, регионов. По Томской области — Северск (15 км, закрытый), Колпашево (270), Стрежевой (700, нефть), Парабель. Сильное направление — научно-образовательный комплекс (ТГУ, ТПУ — образовательный поток), нефтегаз («Томскнефть» ВНК — Стрежевой), химия. Связь с соседями — Новосибирск (270 км, 3-4 часа), Кемерово (320, 4), Красноярск (840, 11). Студенческие потоки — образовательные группы из соседних регионов. На север (Стрежевой) — только сезонные зимники, летом водный путь по Оби.`,

  barnaul: `Барнаул — столица Алтайского края на Р-256 «Чуйский тракт», 3400 км от Москвы, 380 от Новосибирска (5 часов), 200 от Горно-Алтайска. Аэропорт Барнаул принимает рейсы из Москвы, Петербурга, регионов. Сильнейшее туристическое направление — Алтай: Горно-Алтайск (200 км), Манжерок (240), Чемал (320), Усть-Кокса (700), Белуха (через несколько дней пути). Летом — массовый поток на Алтай, машины с багажным минивэном для семей с палатками, ноутбуками, велосипедами. Зимой — горнолыжные курорты Манжерок, Бирюзовая Катунь. По Алтайскому краю — Бийск (160 км, 2 часа), Рубцовск (300, граница с Казахстаном), Камень-на-Оби (200), Заринск. Связь с соседями — Новосибирск (380 км, 5 часов), Кемерово (450), Семипалатинск через границу (Веселоярск, 380). Чуйский тракт — одна из самых красивых дорог России.`,

  kemerovo: `Кемерово — столица Кузбасса на М-53 «Сибирь», 3500 км от Москвы, 250 от Новосибирска (3-4 часа), 320 от Томска (4), 560 от Красноярска. Аэропорт Кемерово принимает рейсы из Москвы, Петербурга, Сочи. По Кузбассу — Новокузнецк (200 км, ЕВРАЗ — крупный поток корпоративных трансферов), Прокопьевск (220), Ленинск-Кузнецкий (130), Белово (140), Юрга (90). Сильнейшее направление — угольная и металлургическая промышленность: КуZbass, Распадская, СУЭК, ЕВРАЗ. Командировки с шахт и разрезов на сменные графики, корпоративные договоры с угольщиками — отдельный сегмент. Туристический поток — Шерегеш (зимой горнолыжный курорт, 500 км, 6 часов) — массовый зимний поток с декабря по апрель. Связь с соседями — Новосибирск (250 км), Томск (320), Красноярск (560), Барнаул (450).`,

  omsk: `Омск стоит на Р-254 «Иртыш», 2700 км от Москвы (32-34 часа), 650 от Новосибирска (8-9), 350 от Тюмени, 540 от Кургана. Международный аэропорт Омск-Центральный принимает рейсы из Москвы, Петербурга, регионов, СНГ. По области — Калачинск (90 км), Тара (300), Исилькуль (150, граница с Казахстаном), Тевриз (440). Сильное направление — нефтепереработка (Газпромнефть-ОНПЗ, один из крупнейших НПЗ страны), химия, машиностроение (Полёт — авиапром). Связь с соседями — Новосибирск (650 км, 8-9 часов), Тюмень (610, 8), Курган (650, 8), Барнаул (840), Павлодар через границу Казахстана (Исилькуль 150 км, потом 270 до Павлодара). Корпоративные клиенты в нефтепереработке и оборонке.`,

  // ===== ДФО =====
  habarovsk: `Хабаровск — главный город Дальнего Востока на Р-297 «Амур», 8400 км от Москвы (на машине, перевозить нерентабельно — местный рынок только в пределах ДФО). Международный аэропорт Хабаровск-Новый принимает рейсы из Москвы, Петербурга, регионов и стран Азии. По Хабаровскому краю — Комсомольск-на-Амуре (380 км, 5-6 часов, Сухой — авиастроение), Совгавань, Николаевск-на-Амуре (только авиа). Сильное направление — оборонка (Сухой в Комсомольске), порт, рыбная промышленность. Связь с соседями — Владивосток (760 км, 10-12 часов по М-60), Биробиджан (180 км, 2.5 часа), Благовещенск (700 км, 10), Чита (1900). С Китаем — через Биробиджан и далее на Фуюань. Возим деловых пассажиров, командировочных, родственников вахтовиков.`,

  yakutsk: `Якутск — столица Республики Саха, 8000 км от Москвы (только авиа реалистично), 1300 от Хабаровска по сезонным зимникам. Аэропорт Якутск — единственный практичный способ попасть в город из европейской части России. По Якутии — Покровск (80 км), Намцы (90), Мирный (диаманты, 1100 км — летом не доехать без подготовки, зимник в декабре-апреле), Нерюнгри (810 км по федералке «Лена», АЯМ), Удачный (диаманты). Сильное направление — алмазодобывающая (АЛРОСА в Мирном и Удачном), золото, нефтегаз. Связь с соседями — на юг по «Лене» на Нерюнгри и далее Сковородино/БАМ (1100 км). Зимы критические: −50°C обычное явление, машины греются непрерывно, специальные масла, дизели не глохнут. Летом дороги местами разрушаются после паводков — нужна подготовка и опыт.`,

  irkutsk: `Иркутск — крупный сибирский центр на Р-255 «Сибирь», 5000 км от Москвы (на машине почти невозможно), 1100 от Красноярска (14-16 часов), 460 от Улан-Удэ (6). Международный аэропорт Иркутск принимает рейсы из Москвы, Петербурга, регионов, СНГ и Азии. Сильнейшее туристическое направление — Байкал: Листвянка (70 км, 1 час), Большие Коты, Слюдянка (110, начало Кругобайкальской железной дороги), Аршан (190), бухта Песчаная. На остров Ольхон — Сахюрта (250 км до парома МРС). По Иркутской области — Ангарск (40 км, нефтехимия), Усолье-Сибирское (90), Шелехов (20, РУСАЛ-Иркутск), Братск (620, ГЭС), Усть-Илимск (1000). Связь с соседями — Улан-Удэ (460 км, 6 часов), Красноярск (1100), Чита (1000). Зимой Байкал замерзает (январь-март), возим на лёд для пеших и автомобильных туров.`,

  vladivostok: `Владивосток — крупнейший порт Дальнего Востока, 9000 км от Москвы, 760 от Хабаровска по М-60 (10-12 часов). Международный аэропорт Кневичи (Артём) принимает рейсы из Москвы, Петербурга, регионов и стран Азии (Пекин, Сеул, Токио — частично). По Приморскому краю — Артём (40 км, аэропорт), Уссурийск (110, граница с Китаем), Находка (180), Партизанск, Спасск-Дальний (240). Сильное направление — порт, рыбный и контейнерный, корейский и японский авторынок (Зелёный угол, Чурикина), судостроение. Туристический поток — остров Русский (по мосту), Эгершельд, маяк Токаревского, бухта Стеклянная. Связь с соседями — Хабаровск (760 км, 10-12 часов), Уссурийск (110, 1.5), граница с Китаем (Полтавка, Краскино), КНДР (Хасан). Часто работаем с автоподборщиками: встреча в порту, осмотр машины, перегон до Хабаровска или Новосибирска.`,

  blagoveshchensk: `Благовещенск стоит на Амуре напротив китайского Хэйхэ, 8000 км от Москвы, 700 от Хабаровска (10 часов). Аэропорт Игнатьево принимает рейсы из Москвы, Хабаровска, Владивостока. Граница с Китаем — через речной мост (открыт в 2022) и пешеходный/автомобильный пункт; зимой по льду Амура (туристы и местные). Поток в Китай и обратно (Хэйхэ — туристы, торговля, медицинские поездки). По Амурской области — Свободный (130 км, космодром Восточный), Белогорск (110), Зея, Тында (820, БАМ). Сильное направление — космодром Восточный, угольные разрезы, золотодобыча. Связь с соседями — Хабаровск (700 км, 10 часов), Якутск (1100 по зимнику, летом нереально). С 2022 года потоки выросли после открытия моста через Амур.`,

  chita: `Чита — крупный город Забайкалья на М-58 «Амур» и Р-258, 6200 км от Москвы (на машине нерентабельно), 1000 от Улан-Удэ (12-14 часов), 1100 от Иркутска. Аэропорт Кадала принимает рейсы из Москвы, Петербурга, регионов. По Забайкальскому краю — Краснокаменск (450 км, уран), Борзя (380), Нерчинск (250), Агинское (140). Сильное направление — горнорудная (уран в Краснокаменске), золото, военные части (граница с Китаем и Монголией). Туристический поток — Чарские пески (далеко), Алханай (национальный парк, 280 км). Связь с соседями — Улан-Удэ (1000 км, 12-14 часов), Иркутск (1100), на восток к Хабаровску (1900 км по М-58, минимум двое суток). Граница с Монголией (Кяхта через Улан-Удэ, Соловьёвск) и Китаем (Забайкальск 460 км).`,

  'ulan-ude': `Улан-Удэ — столица Бурятии, 5800 км от Москвы, 460 от Иркутска (6 часов), 230 от Кяхты (граница с Монголией). Международный аэропорт Байкал принимает рейсы из Москвы, Петербурга, регионов, Монголии. Сильнейшее туристическое направление — Байкал с восточного берега (Гремячинск, Энхалук, Турка — 130-150 км), Иволгинский дацан (35 км — резиденция Пандито Хамбо-ламы), Этнографический музей. По Бурятии — Гусиноозёрск (110 км), Кяхта (граница с Монголией, 230 км — туристы и грузы), Северобайкальск (только круговой путь через Иркутск или зимник). Связь с соседями — Иркутск (460 км, 6 часов), Чита (1000 км, 12-14 часов). С Монголией работаем по согласованной маршрутке (Кяхта — Сухэ-Батор — Улан-Батор).`,

  kyzyl: `Кызыл — столица Тувы, 4700 км от Москвы, 410 от Абакана (7-8 часов, единственная связь с Сибирью по Р-257 «Енисей»). Аэропорт Кызыл принимает рейсы из Москвы и Красноярска. Туристический поток — центр Азии (стелла), Тоджа, Енисей, шаманские места. По Туве — Шагонар (130 км), Чадан (220), Туран (60, ущелье Шуй), Эрзин (250, граница с Монголией). Связь с соседями — только через Абакан (410 км по Енисею через Усинский тракт — горный, зимой опасный). Граница с Монголией работает (Хандагайты, Цаган-Толгой). Дороги горные, зимой опасные (Усинский перевал), летом — туристические потоки на сплавы по Енисею и треккинг. Работаем на полноприводных машинах с опытными водителями.`,

  'yuzhno-sahalinsk': `Южно-Сахалинск — столица Сахалинской области, остров — только авиа из материка (8 часов через Москву). Аэропорт Хомутово принимает рейсы из Москвы, Петербурга, Хабаровска, Владивостока, Японии (частично). По Сахалину — Корсаков (40 км, порт), Холмск (90, паромное сообщение с Ванино), Невельск (160), Поронайск (290), Оха (нефть, 800 км — длинный путь по острову). На Курилы — авиа из Южно-Сахалинска (Итуруп, Кунашир, Шикотан). Сильное направление — нефтегаз (Сахалин-1, Сахалин-2 — Корсаков, Пригородное), рыбная промышленность, морепродукты. Туристический поток — Холмск (паромы и пляжи), бухта Тихая, мыс Анива (маяк), горнолыжный курорт «Горный воздух». Связь с материком только морем (паром Холмск — Ванино) или авиа. Дороги по острову — местами разрушены тайфунами, нужен подходящий транспорт.`,

  birobidzhan: `Биробиджан — столица Еврейской автономной области, 7300 км от Москвы, 180 от Хабаровска (2.5 часа), 700 от Благовещенска. Аэропорт Биробиджан обслуживает в основном внутренние местные рейсы — большинство международных через Хабаровск. По области — Облучье (160 км), Ленинское (на Амуре, китайская граница), Биджан, Смидович. С Китаем — через Ленинское и далее на Тунцзян (логистический коридор, работает). Связь с соседями — Хабаровск (180 км, 2.5 часа), Благовещенск (700, 10), Владивосток (900). Сильное направление — поток корпоративных трансферов в Хабаровск к/от аэропорта Новый. Часто работаем как «спутник» Хабаровска — крупный город Дальнего Востока в часе езды.`,

  // ===== ПИЛОТНЫЕ 9 ГОРОДОВ (контент уже был — не трогаем) =====
  yaroslavl: `Ярославль — входные ворота в Золотое кольцо, связь с Москвой идёт по М-8 (4-5 часов, 270 км). Основные направления из Ярославля — Москва и Петербург для деловых поездок, Кострома-Иваново-Владимир-Суздаль для туристических маршрутов, Рыбинск и Углич по Волге для выездов к водохранилищу. Международный аэропорт Туношна обслуживает в основном грузовые рейсы и чартеры, поэтому трансферы в Шереметьево и Пулково — постоянный запрос. Сезонный пик — с мая по октябрь: круизные рейсы с Речного вокзала, экскурсионные группы, паломнические поездки в Толгский монастырь. Часто возим между Ярославлем и Костромой, Переславлем-Залесским, Ростовом Великим — города Золотого кольца традиционно смотрят пакетом, и маршрут можно распланировать на 2-3 остановки с ожиданием водителя.`,

  vladimir: `Владимир соединён с Москвой по М-7 «Волга» (3-3.5 часа, 180 км) и с Нижним Новгородом в другую сторону (4 часа, 240 км). Пригородные аэропорты Семязино и Чкаловский работают только для малой авиации, поэтому трансферы во Внуково, Домодедово и Шереметьево — стабильный поток. Второй крупный запрос — туристические поездки в Суздаль (30 км), Боголюбово и Гусь-Хрустальный. Для бизнес-пассажиров часто строим связку Владимир — Иваново — Ковров — Муром по региональным дорогам. Из Владимира удобно ехать в Тольятти (АВТОВАЗ) и Нижний Новгород по М-7: 7 и 4 часа соответственно, часто командируют специалистов автопрома.`,

  kaluga: `Калуга — 180 км до Москвы по Киевскому шоссе (М-3), 2.5-3 часа в пути. Близость к столице формирует основной поток: командировки на столичные переговоры, трансферы во Внуково (120 км) и Домодедово (170 км), Шереметьево реже. Отдельный пласт — промышленный кластер: технопарки Грабцево, Росва, индустриальный парк Ворсино. Из аэропортов подаём машину прямо к корпусу предприятия — Samsung, L'Oreal, PSMA, Volkswagen (бывший завод), фармкомпании. Для туристов — поездки в Тарусу (80 км), Боровск, Оптину Пустынь (110 км) и Козельск. По региональным направлениям часто ездят в Тулу (100 км, 1.5 часа) и Брянск (250 км, 3.5 часа).`,

  oryol: `Орёл стоит на трассе М-2 «Крым», 370 км до Москвы, 170 до Курска, 240 до Брянска — это формирует основной поток поездок. Аэропорт Южный не принимает рейсы с 2022 года, поэтому все авиаперелёты через Воронеж (230 км), Курск (170 км) или Москву. Сильное бизнес-направление — столичные командировки: выезжаем в 4-5 утра под утренние встречи, к 9-10 в Москве. Туристический сегмент — Спасское-Лутовиново (усадьба Тургенева), Новосиль, поездки в Тульскую область. Работаем и по СВО-направлениям: Белгородская область, ЛНР, ДНР — запросы стабильные с 2022 года, возим гуманитарку, командировочных, родственников.`,

  kursk: `Курск лежит на юго-западной оси: Москва (530 км), Белгород (150), Воронеж (220), Брянск (220), Орёл (170). Аэропорт Восточный работает в ограниченном режиме (внутренние рейсы из Москвы и обратно), полноценные международные перелёты — через московские или воронежский аэропорт. Основные потоки из Курска — деловые и пригородные трансферы в соседние регионы, металлургическая командировка на Михайловский ГОК (40 км), поездки в Железногорск (100 км) и Старый Оскол (150 км). С 2022 года стабильно возим по СВО-маршрутам и в прифронтовую Белгородскую область. Для граждан Украины и ДНР/ЛНР — поездки в Россию из пограничных пунктов (Гоптовка, Суджа).`,

  tver: `Тверь — середина северо-западного коридора Москва — Петербург. По М-10 «Россия» и скоростной М-11 «Нева» до обеих столиц одинаково удобно: 170 км до Москвы (2-2.5 часа), 500 до Петербурга (6-7 часов). Это определяет главный поток: деловые поездки в обе стороны и трансферы в Шереметьево (140 км) и Пулково (500 км). Аэропорт Змеёво не принимает пассажирские рейсы. Сильное направление — Осташков и Селигер (170 км), куда ездят круглый год: летом туристы, зимой на рыбалку и в санатории. Из Твери часто возим в Торжок, Ржев, Вышний Волочёк, Бологое — это исторические города Тверской области с паломническим и усадебным туризмом. Транзит в Карелию и Ленинградскую область по М-11 — 4-5 часов до Петербурга при свободной трассе.`,

  belgorod: `Белгород — южная точка ЦФО, 700 км до Москвы по М-2 «Крым», 150 до Курска, 260 до Воронежа, 40 км до российско-украинской границы. Международный аэропорт Белгород работает ограниченно: часть рейсов переведена в Воронеж. Сильный поток — деловые поездки по Белгородской области (металлургия: Оскольский ЭМК, Лебединский ГОК, АПК), трансферы в столичные аэропорты и в Воронеж. С 2022 года добавились регулярные поездки в Старый Оскол, Губкин, Шебекино и приграничные районы — с учётом оперативной обстановки. Для граждан, возвращающихся из ЛНР и ДНР через российскую границу, возим по направлениям пограничных пунктов. Возим и в Харьковскую область (Волчанск, Шебекинский р-н) — маршруты согласовываются с диспетчером за сутки.`,

  voronezh: `Воронеж — узел трассы М-4 «Дон», связывающей Москву с югом России. До Москвы 530 км (6-7 часов), до Ростова-на-Дону 550 (6-7), до Волгограда 580, до Краснодара 960, до Сочи 1500. Воронежский международный аэропорт принимает внутренние и ряд международных рейсов — но для части направлений всё равно выгоднее ехать в Москву на машине. Сильный южный поток: летом сотни поездок к морю (Анапа, Геленджик, Сочи, Крым) — семьи с багажом выбирают минивэн, чтобы не пересаживаться с поезда на автобус и не зависеть от расписаний. Зимой добавляются горнолыжные направления — Красная Поляна через Краснодар. Рабочие потоки — Липецк, Белгород, Тамбов, Старый Оскол; часто ездят корпоративные группы на объекты ЧОГОК, НЛМК и агрохолдингов Черноземья.`,
}

